//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, RwLock, RwLockReadGuard, RwLockWriteGuard};

pub type PlayerId = u32;

#[derive(Default)]
struct ScoreState {
    players: HashMap<PlayerId, i64>,
    total: i64,
}

/// Clones share the same scores, so each match thread keeps its own handle.
#[derive(Clone, Default)]
pub struct Board {
    state: Arc<RwLock<ScoreState>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    fn read_state(&self) -> RwLockReadGuard<'_, ScoreState> {
        self.state.read().unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    fn write_state(&self) -> RwLockWriteGuard<'_, ScoreState> {
        self.state.write().unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        let mut state = self.write_state();
        if let Some(previous) = state.players.insert(id, score) {
            state.total -= previous;
        }
        state.total += score;
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let mut state = self.write_state();
        let player_score = state
            .players
            .get_mut(&id)
            .unwrap_or_else(|| panic!("unknown PlayerId {id}; expected registered player"));
        *player_score += points;
        state.total += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        let mut state = self.write_state();
        if !state.players.contains_key(&from) {
            panic!("unknown from PlayerId {from}; expected registered player");
        }
        if !state.players.contains_key(&to) {
            panic!("unknown to PlayerId {to}; expected registered player");
        }
        if from == to {
            return;
        }
        *state.players.get_mut(&from).unwrap() -= points;
        *state.players.get_mut(&to).unwrap() += points;
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        let state = self.read_state();
        *state
            .players
            .get(&id)
            .unwrap_or_else(|| panic!("unknown PlayerId {id}; expected registered player"))
    }

    pub fn total(&self) -> i64 {
        self.read_state().total
    }
}

